  function normalizeLanguage(value) {
    const language = String(value || '').trim().replace(/_/g, '-').toLowerCase();
    if (/^zh(?:-|$)/.test(language)) return /(?:^|-)hant(?:-|$)|(?:^|-)(?:tw|hk|mo)(?:-|$)/.test(language) ? 'zh-TW' : 'zh-CN';
    const base = language.split('-')[0];
    return SUPPORTED_LANGUAGES.includes(base) ? base : 'en';
  }
  function normalizeChoice(value) {
    const choice = typeof value === 'string' ? value.trim().toLowerCase() : '';
    return INTERFACE_LANGUAGES.find(item => item.value.toLowerCase() === choice)?.value || 'auto';
  }
  function resolveLanguage(choice, automaticLanguage) {
    const selected = normalizeChoice(choice);
    return selected === 'auto' ? normalizeLanguage(automaticLanguage) : selected;
  }
  function browserLanguage(environment = globalThis) {
    let language;
    try { language = environment.chrome?.i18n?.getUILanguage(); } catch { /* Browser locale API unavailable. */ }
    return normalizeLanguage(language || environment.navigator?.language || 'en');
  }
  function t(key, language, vars = {}) {
    const text = catalog[normalizeLanguage(language)][key] ?? catalog.en[key] ?? String(key);
    return text.replace(/\{([A-Za-z][A-Za-z0-9_]*)\}/g, (match, name) =>
      Object.prototype.hasOwnProperty.call(vars, name) ? String(vars[name]) : match);
  }
  function apply(target, language) {
    const locale = normalizeLanguage(language);
    const selector = '[data-i18n],[data-i18n-aria],[data-i18n-placeholder],[data-i18n-title]';
    const elements = [...(target.querySelectorAll?.(selector) || [])];
    if (target.matches?.(selector)) elements.unshift(target);
    for (const element of elements) {
      let vars = {};
      try { vars = JSON.parse(element.getAttribute('data-i18n-vars') || '{}'); } catch { /* Static label. */ }
      if (!vars || typeof vars !== 'object') vars = {};
      const key = element.getAttribute('data-i18n');
      if (key) element.textContent = t(key, locale, vars);
      for (const [source, attribute] of [['data-i18n-aria','aria-label'],['data-i18n-placeholder','placeholder'],['data-i18n-title','title']]) {
        const attributeKey = element.getAttribute(source);
        if (attributeKey) element.setAttribute(attribute, t(attributeKey, locale, vars));
      }
    }
    if (target.documentElement) {
      target.documentElement.lang = locale;
      target.documentElement.dir = locale === 'ar' ? 'rtl' : 'ltr';
    }
    return locale;
  }
  // API and official localhost ACP onboarding share the same localized UI.
